import re

_VERSION = re.compile(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)")
# type: lower-case letters; optional (scope) with anything but parentheses,
# non-empty; optional "!" right before the colon; exactly one space after the
# colon, followed by text that does not start with a space.
_HEADER = re.compile(r"([a-z]+)(?:\(([^()]+)\))?(!)?: (\S.*)")
_BREAKING_FOOTER = re.compile(r"BREAKING[ -]CHANGE: ")

_NONE, _FIX, _FEAT, _BREAKING = 0, 1, 2, 3


def _classify(message):
    """Return the change level of one commit message (see TASK.md)."""
    lines = message.split("\n")
    m = _HEADER.fullmatch(lines[0])
    if m is None:
        return _NONE  # a header in another form does not count at all
    commit_type, bang = m.group(1), m.group(3)
    if bang:
        return _BREAKING
    for line in lines[1:]:
        if _BREAKING_FOOTER.match(line):
            return _BREAKING
    if commit_type == "feat":
        return _FEAT
    if commit_type == "fix":
        return _FIX
    return _NONE


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    if not isinstance(current, str):
        raise ValueError(f"not a version: {current!r}")
    v = _VERSION.fullmatch(current)
    if v is None:
        raise ValueError(f"not a version: {current!r}")
    major, minor, patch = (int(x) for x in v.groups())

    level = _NONE
    for message in commits:
        level = max(level, _classify(message))

    if level == _NONE:
        return current

    if major == 0:
        if level == _BREAKING:
            return f"0.{minor + 1}.0"
        return f"0.{minor}.{patch + 1}"

    if level == _BREAKING:
        return f"{major + 1}.0.0"
    if level == _FEAT:
        return f"{major}.{minor + 1}.0"
    return f"{major}.{minor}.{patch + 1}"
